<script setup>
import { computed, ref } from 'vue';
const props = defineProps({
  loading: Boolean,
  actions: { type: Array, default: () => [] },
  categories: { type: Array, default: () => [] },
  health: { type: Array, default: () => [] },
  lots: { type: Array, default: () => [] },
  liquids: { type: Array, default: () => [] },
  work: { type: Array, default: () => [] }
});
const emit = defineEmits(['navigate', 'category']);
const selectedRisk = ref(null), riskPage = ref(1);
const riskLots = computed(() => props.lots.filter(row => Number(row.on_hand) > 0 && (['expired', 'expiring'].includes(selectedRisk.value?.key) ? row.expiry_status === selectedRisk.value.key : row.available_reason === selectedRisk.value?.key)));
function openRisk(item) { selectedRisk.value = item; riskPage.value = 1; }
const number = value => Number(value || 0).toLocaleString('zh-CN', { maximumFractionDigits: 3 });
const readyLiquids = computed(() => props.liquids.filter(row => row.source_type === 'production' && ['raw_ready', 'awaiting_packaging'].includes(row.production_status)));
const rawVolume = computed(() => readyLiquids.value.filter(row => row.volume_basis === 'actual').reduce((sum, row) => sum + Number(row.on_hand || 0), 0));
const estimatedVolume = computed(() => readyLiquids.value.filter(row => row.volume_basis !== 'actual').reduce((sum, row) => sum + Number(row.on_hand || 0), 0));
const risks = computed(() => props.health.filter(item => item.value > 0));
</script>

<template>
  <div class="inventory-overview" :aria-busy="loading">
    <header class="io-heading"><h3>库存与采购</h3><button type="button" @click="emit('navigate', 'stock')">查看全部库存 →</button></header>
    <section class="io-actions" aria-label="采购待办"><button v-for="item in actions" :key="item.key" type="button" :title="item.hint" :class="{ urgent: item.urgent && item.value > 0, 'has-work': item.value > 0 }" @click="emit('navigate', item.target)"><span>{{ item.label }}</span><strong>{{ loading ? '—' : number(item.value) }}<small>{{ item.unit }}</small></strong><i>→</i></button></section>
    <section v-if="risks.length || work.some(item => item.value > 0)" class="io-attention" aria-label="需要关注"><span class="io-attention-label">需要关注</span><button v-for="item in risks" :key="item.key" type="button" :class="{ danger: item.key === 'expired' }" @click="openRisk(item)">{{ item.label }}<strong>{{ number(item.value) }} 批</strong><b>›</b></button><button v-for="item in work.filter(item => item.value > 0)" :key="item.key" type="button" @click="emit('navigate', item.target)">{{ item.label }}<strong>{{ number(item.value) }} {{ item.unit }}</strong><b>›</b></button></section>
    <section class="io-panel io-stock"><header><h4>原料与包装库存</h4><span>{{ categories.length }} 个分类</span></header><div class="io-table-wrap"><table><thead><tr><th>物料分类</th><th>可用数量</th><th>已预占</th><th>库存批次</th><th></th></tr></thead><tbody><tr v-for="item in categories" :key="item.category"><td><strong>{{ item.category_name }}</strong><small>{{ item.product_count }} 种物料</small></td><td class="io-available">{{ item.uom === '多单位' ? '按单位查看' : number(item.available) }}<small v-if="item.uom !== '多单位'">{{ item.uom }}</small></td><td>{{ item.uom === '多单位' ? '—' : number(item.reserved) }}<small v-if="item.uom !== '多单位'">{{ item.uom }}</small></td><td>{{ number(item.lot_count) }}</td><td><button type="button" :aria-label="'查看' + item.category_name + '库存'" @click="emit('category', item)">查看明细 →</button></td></tr></tbody></table></div><div v-if="!categories.length" class="io-empty">{{ loading ? '正在加载库存…' : '暂无库存记录' }}</div></section>
    <section class="io-panel io-liquids"><header><h4>待出酒原液 <span>{{ readyLiquids.length }} 批</span></h4><div class="io-liquid-total"><span>剩余酒液</span><strong>{{ loading ? '—' : number(rawVolume) }}<small>L</small></strong><button type="button" @click="emit('navigate', 'raw-stock')">查看原液 →</button></div></header><div class="io-liquid-list"><button v-for="row in readyLiquids.slice(0, 5)" :key="row.batch_id" type="button" @click="emit('navigate', 'raw-stock')"><span><strong>{{ row.product.name }}</strong><small>{{ row.factory.name }} · {{ row.batch_name }}</small></span><span :class="{ 'io-warning': row.tank_verified === false }">{{ row.tank_verified === false ? '存放位置待核对' : row.tank || '待确认库位' }}</span><strong>{{ number(row.on_hand) }} <small>L{{ row.volume_basis !== 'actual' ? ' · 估算' : '' }}</small></strong></button></div><p v-if="estimatedVolume" class="io-estimated">另有 {{ number(estimatedVolume) }} L 计划估算量，待确认实际产量</p><div v-if="!readyLiquids.length" class="io-empty">{{ loading ? '正在加载原液…' : '暂无待出酒原液' }}</div></section>
    <Teleport to="body"><div v-if="selectedRisk" class="io-risk-mask" @click.self="selectedRisk = null" @keydown.esc="selectedRisk = null"><section class="io-risk-dialog io-panel" role="dialog" aria-modal="true" :aria-label="selectedRisk.label + '批次'"><header><h4>{{ selectedRisk.label }} <span>{{ riskLots.length }} 批</span></h4><button type="button" autofocus aria-label="关闭库存批次" @click="selectedRisk = null">关闭 ×</button></header><div class="io-risk-body io-table-wrap"><table><thead><tr><th>物料 / 批次</th><th>有效期</th><th>账面数量</th><th>可用数量</th></tr></thead><tbody><tr v-for="lot in riskLots.slice((riskPage - 1) * 20, riskPage * 20)" :key="lot.id"><td><strong>{{ lot.product?.name }}</strong><small>{{ lot.name }}</small></td><td>{{ lot.expiration_date || '未设置' }}</td><td>{{ number(lot.on_hand) }} {{ lot.uom }}</td><td>{{ number(lot.available) }} {{ lot.uom }}</td></tr></tbody></table></div><footer><button type="button" :disabled="riskPage <= 1" @click="riskPage--">上一页</button><span>{{ riskPage }} / {{ Math.max(1, Math.ceil(riskLots.length / 20)) }}</span><button type="button" :disabled="riskPage * 20 >= riskLots.length" @click="riskPage++">下一页</button></footer></section></div></Teleport>
  </div>
</template>

<style scoped>
