.io-liquid-list>button>span:first-child{display:grid;gap:5px}.io-liquid-list strong{font-weight:500}.io-liquid-list small{font-size:11px;font-weight:400;color:var(--text-muted,#8f8b81)}.io-liquid-list>button>strong{text-align:right;font-size:15px;font-variant-numeric:tabular-nums}.io-warning{color:#d8b467}.io-estimated{margin:0;padding:10px 18px;font-size:11px;color:var(--text-muted)}.inventory-overview button:focus-visible{outline:2px solid #d5ac52;outline-offset:-3px}@media(max-width:800px){.io-actions{grid-template-columns:repeat(2,minmax(0,1fr))}.io-actions>button{padding:14px 16px}.io-actions>button:nth-child(2){border-right:0}.io-actions>button:nth-child(-n+2){border-bottom:1px solid var(--border-default)}.io-liquid-list>button{grid-template-columns:minmax(0,1fr) 100px;gap:8px}.io-liquid-list>button>span:nth-child(2){grid-column:1;grid-row:2}.io-liquid-list>button>strong{grid-column:2;grid-row:1/3}.io-stock td:first-child small{display:block;margin:5px 0 0}}@media(max-width:480px){.io-liquid-total{gap:10px}.io-liquid-total>span{display:none}.io-panel>header{padding:12px}.io-stock :is(th,td){padding-left:12px;padding-right:12px}.io-heading h3{font-size:17px}}
</style>
<style scoped>
.io-risk-mask{position:fixed;inset:0;z-index:10020;display:grid;place-items:center;padding:24px;background:#0009}.io-risk-dialog{width:min(800px,95vw);max-height:85vh;display:flex;flex-direction:column;background:var(--bg-card,#25231e);color:var(--text-primary,#e8e4db)}.io-risk-dialog>header{flex-shrink:0}.io-risk-dialog h4 span{margin-left:8px}.io-risk-body{overflow:auto;min-height:100px}.io-risk-dialog table{width:100%;border-collapse:collapse;font-size:12px}.io-risk-dialog th{color:var(--text-muted,#8f8b81);font-weight:400;text-align:left}.io-risk-dialog :is(td,th){padding:13px 18px;border-bottom:1px solid #ffffff0a;white-space:nowrap}.io-risk-dialog td small{display:block;margin-top:5px;color:var(--text-muted,#8f8b81)}.io-risk-dialog td strong{font-weight:500}.io-risk-dialog footer{display:flex;align-items:center;justify-content:flex-end;gap:14px;padding:14px 18px;border-top:1px solid #ffffff0c;font-size:12px}.io-risk-dialog footer button{border:1px solid #ffffff20;background:none;border-radius:6px;color:inherit;padding:7px 10px;cursor:pointer}.io-risk-dialog button:disabled{opacity:.4;cursor:default}
</style>
